async function createNotification(env2, userId, title2, message, type = "info") {
  try {
    const id = generateCustomId("YA-NTF");
    await env2.DB.prepare(
      "INSERT INTO Notifications (id, user_id, title, message, type) VALUES (?, ?, ?, ?, ?)"
    ).bind(id, userId, title2, message, type).run();
    const subs = await env2.DB.prepare(
      "SELECT subscription_json FROM PushSubscriptions WHERE user_id = ?"
    ).bind(userId).all();
    if (subs.results && subs.results.length > 0) {
      for (const subRecord of subs.results) {
        try {
          const subscription = JSON.parse(subRecord.subscription_json);
          await sendWebPush(env2, subscription, {
            title: title2,
            body: message,
            icon: "/logo.png",
            data: { url: "/student/notifications" }
          });
        } catch (e) {
          console.error("Push delivery failed for a sub:", e);
        }
      }
    }
  } catch (error4) {
    console.error("Failed to create notification:", error4);
  }
}
__name(createNotification, "createNotification");
async function sendWebPush(env2, subscription, payload) {
  try {
    const publicKey = await env2.PLATFORM_SECRETS.get("VAPID_PUBLIC_KEY");
    const privateKey = await env2.PLATFORM_SECRETS.get("VAPID_PRIVATE_KEY");
    const subject = await env2.PLATFORM_SECRETS.get("VAPID_SUBJECT");
    if (!publicKey || !privateKey || !subject) {
      console.warn("VAPID keys or subject not configured in PLATFORM_SECRETS");
      return;
    }
    import_web_push.default.setVapidDetails(subject, publicKey, privateKey);
    await import_web_push.default.sendNotification(subscription, JSON.stringify(payload));
  } catch (error4) {
    if (error4.statusCode === 410 || error4.statusCode === 404) {
      console.warn("Push subscription expired or invalid. Deleting from DB.");
      try {
        await env2.DB.prepare("DELETE FROM PushSubscriptions WHERE subscription_json = ?").bind(JSON.stringify(subscription)).run();
      } catch (dbErr) {
        console.error("Failed to delete expired subscription from DB", dbErr);
      }
    } else {
      console.error("Error sending web push:", error4);
    }
  }
}
