async function handleListLessons(request3, env2, courseId) {
  try {
    const token = getCookie(request3, "session");
    let allowed = false;
    let isPaid = false;
    let hasActiveSubscription = false;
    let subscriptionCourseAccess = false;
    let userId = null;
    if (token) {
      try {
        const jwtSecret = await getSecret(env2, "JWT_SECRET");
        if (!jwtSecret) throw new Error("JWT_SECRET missing");
        const payload = await verifyJWT(token, jwtSecret);
        userId = payload.sub;
        if (payload.role === "admin" || payload.role === "teacher") {
          allowed = true;
          isPaid = true;
        } else {
          const enrollment = await env2.DB.prepare(
            "SELECT payment_status FROM Enrollments WHERE user_id = ? AND course_id = ?"
          ).bind(userId, courseId).first();
          if (enrollment) {
            allowed = true;
            isPaid = enrollment.payment_status === "paid";
          }
          if (!isPaid) {
            const profile3 = await getUserAccessProfile(userId, env2);
            hasActiveSubscription = profile3.hasActiveSub;
            subscriptionCourseAccess = userAccessProfileAllowsCourse(profile3, courseId);
            if (subscriptionCourseAccess) {
              allowed = true;
              isPaid = true;
            }
          }
        }
      } catch (e) {
      }
    }
    const url = new URL(request3.url);
    const bookId = url.searchParams.get("book_id");
    let results;
    if (bookId) {
      const q = await env2.DB.prepare("SELECT * FROM Lessons WHERE book_id = ? ORDER BY order_index ASC").bind(bookId).all();
      results = q.results;
    } else {
      const q = await env2.DB.prepare("SELECT * FROM Lessons WHERE course_id = ? OR book_id IN (SELECT book_id FROM CourseBooks WHERE course_id = ?) ORDER BY order_index ASC").bind(courseId, courseId).all();
      results = q.results;
    }
    let completedLessonIds = [];
    if (userId && allowed) {
      const completedQuery = await env2.DB.prepare(
        `SELECT CL.lesson_id
         FROM CompletedLessons CL
         JOIN Lessons L ON CL.lesson_id = L.id
         WHERE CL.user_id = ? AND (L.course_id = ? OR L.book_id IN (SELECT book_id FROM CourseBooks WHERE course_id = ?))`
      ).bind(userId, courseId, courseId).all();
      if (completedQuery.results) {
        completedLessonIds = completedQuery.results.map(
          (r2) => r2.lesson_id
        );
      }
    }
    if (!allowed) {
      const safeResults = results.map((r2) => ({
        id: r2.id,
        chapter_title: r2.chapter_title,
        title: r2.title,
        type: r2.type,
        order_index: r2.order_index,
        is_free: r2.is_free
      }));
      return new Response(
        JSON.stringify({ lessons: safeResults, locked: true }),
        { status: 200, headers: { "Content-Type": "application/json" } }
      );
    }
    const filteredResults = results.map((r2) => {
      if (!isPaid && r2.is_free !== 1) {
        return {
          ...r2,
          content_url: "",
          text_content: "\u{1F512} This content is premium. Please enroll/pay to unlock.",
          is_locked: true
        };
      }
      return { ...r2, is_locked: false };
    });
    return new Response(
      JSON.stringify({
        lessons: filteredResults,
        locked: !isPaid,
        completedLessonIds,
        isEnrolled: allowed,
        paymentStatus: isPaid ? "paid" : "unpaid",
        hasActiveSubscription,
        subscriptionCourseAccess
      }),
      { status: 200, headers: { "Content-Type": "application/json" } }
    );
  } catch (error4) {
    return handleGlobalError(error4, "Course.Lessons", env2, request3);
  }
}
