async function handleRecordingAction(request3, env2) {
  try {
    const auth = await requireAdminOrTeacher(request3, env2);
    const { meetingId, action } = await request3.json();
    if (action === "start") {
      const data = await callRealtimeAPI(env2, "/recordings", "POST", {
        meeting_id: meetingId,
        video_config: {
          codec: "H264",
          width: 1280,
          height: 720,
          export_file: true
        },
        audio_config: { codec: "AAC", channel: "stereo", export_file: true }
      });
      const recordingId = data?.data?.id || data?.result?.id;
      if (recordingId) {
        await env2.DB.prepare(
          'UPDATE LiveSessions SET recording_id = ?, recording_status = "pending" WHERE rtc_room_id = ?'
        ).bind(recordingId, meetingId).run();
      }
      return new Response(JSON.stringify(data), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    if (action === "stop") {
      const activeData = await callRealtimeAPI(
        env2,
        `/recordings/active-recording/${meetingId}`,
        "GET",
        null,
        true
      );
      let recordingId = activeData?.data?.id || activeData?.result?.id;
      if (!recordingId) {
        const listRecs = await callRealtimeAPI(env2, `/recordings`, "GET", null);
        const recordsArray = listRecs?.data || listRecs?.result || [];
        const matchedRec = recordsArray.find(
          (r2) => r2.meeting_id === meetingId
        );
        if (matchedRec) recordingId = matchedRec.id;
      }
      if (!recordingId) {
        return new Response(JSON.stringify({ error: "No active recording" }), {
          status: 404,
          headers: { "Content-Type": "application/json" }
        });
      }
      const data = await callRealtimeAPI(
        env2,
        `/recordings/${recordingId}`,
        "PUT",
        { action: "stop" }
      );
      return new Response(JSON.stringify(data), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    return new Response(JSON.stringify({ error: "Invalid action" }), {
      status: 400,
      headers: { "Content-Type": "application/json" }
    });
  } catch (error4) {
    return handleGlobalError(error4, "Live.RecordingAction", env2, request3);
  }
}
