async function addCreditsToWallet(env2, userId, amount, reason, referenceType, referenceId) {
  const safeAmount = normalizeNonNegativeInt(amount);
  if (safeAmount <= 0) throw new Error("Credit amount must be greater than 0");
  await env2.DB.prepare(
    `INSERT INTO CreditWallets (id, user_id, balance, lifetime_credits, updated_at)
     VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP)
     ON CONFLICT(user_id) DO UPDATE SET
       balance = balance + ?,
       lifetime_credits = lifetime_credits + ?,
       updated_at = CURRENT_TIMESTAMP`
  ).bind(crypto.randomUUID(), userId, safeAmount, safeAmount, safeAmount, safeAmount).run();
  const balance = await getCreditBalance(env2, userId);
  await env2.DB.prepare(
    `INSERT INTO CreditLedger (id, user_id, change_amount, balance_after, reason, reference_type, reference_id)
     VALUES (?, ?, ?, ?, ?, ?, ?)`
  ).bind(
    crypto.randomUUID(),
    userId,
    safeAmount,
    balance.balance,
    reason,
    referenceType || null,
    referenceId || null
  ).run();
  return balance;
}
