async function deductCreditsFromWallet(env2, userId, amount, reason, referenceType, referenceId) {
  const safeAmount = normalizeNonNegativeInt(amount);
  const before = await getCreditBalance(env2, userId);
  if (safeAmount <= 0) return { ok: true, balance: before.balance };
  const updateResult = await env2.DB.prepare(
    `UPDATE CreditWallets
     SET balance = balance - ?, updated_at = CURRENT_TIMESTAMP
     WHERE user_id = ? AND balance >= ?`
  ).bind(safeAmount, userId, safeAmount).run();
  const changed = Number(updateResult?.meta?.changes || updateResult?.changes || 0);
  if (changed < 1) {
    return { ok: false, balance: before.balance };
  }
  const balance = await getCreditBalance(env2, userId);
  await env2.DB.prepare(
    `INSERT INTO CreditLedger (id, user_id, change_amount, balance_after, reason, reference_type, reference_id)
     VALUES (?, ?, ?, ?, ?, ?, ?)`
  ).bind(
    crypto.randomUUID(),
    userId,
    -safeAmount,
    balance.balance,
    reason,
    referenceType || null,
    referenceId || null
  ).run();
  return { ok: true, balance: balance.balance };
}
