async function searchCourseContent(env2, query, topK = 5) {
  try {
    if (!env2.AI_SEARCH) {
      console.warn("[Search] AI_SEARCH binding missing");
      return "";
    }
    const instance = env2.AI_SEARCH.get("ya-lms-content");
    const response = await instance.search({
      query,
      ai_search_options: { top_k: topK }
    });
    const results = response?.results || [];
    if (results.length === 0) return "";
    const formatted = results.map((r2) => {
      const meta = r2.metadata || {};
      return `[Source: ${meta.title || "Unknown"}]
${r2.content || ""}`;
    }).join("\n\n");
    return `
[AI SEARCH RESULTS from ya-lms-content]:
${formatted}
`;
  } catch (e) {
    console.error("[Search Error]", e);
    return "";
  }
}
