async function indexLessonToAISearch(env2, lesson) {
  try {
    if (!env2.AI_SEARCH) {
      console.warn("[AI Search] AI_SEARCH binding missing, skipping index");
      return;
    }
    const instance = env2.AI_SEARCH.get("ya-lms-content");
    const content = [
      lesson.title || "",
      lesson.text_content || "",
      lesson.text_content_hi || ""
    ].filter(Boolean).join("\n\n");
    if (!content.trim()) return;
    await instance.items.uploadAndPoll(`lesson-${lesson.id}.md`, content, {
      metadata: {
        lesson_id: lesson.id,
        course_id: lesson.course_id,
        title: lesson.title || "",
        type: lesson.type || "",
        chapter_title: lesson.chapter_title || "",
        order_index: lesson.order_index ?? 0
      }
    });
  } catch (e) {
    console.error(`[AI Search] Index failed for lesson ${lesson.id}:`, e);
  }
}
