    const payload = await requireAuth(request3, env2);
    const { planId } = await request3.json();
    const plan = await env2.DB.prepare(
      "SELECT * FROM SubscriptionPlans WHERE id = ? AND is_active = 1"
    ).bind(planId).first();
    if (!plan)
      return new Response(
        JSON.stringify({ error: "Subscription plan not found" }),
        { status: 404 }
      );
    if (!plan.razorpay_plan_id)
      return new Response(
        JSON.stringify({
          error: "This plan is not yet linked to Razorpay. Contact admin."
        }),
        { status: 503 }
      );
    const razorpayKey = await getSecret(env2, "RAZORPAY_KEY_ID");
    const razorpaySecret = await getSecret(env2, "RAZORPAY_KEY_SECRET");
    if (!razorpayKey || !razorpaySecret) {
      return new Response(
        JSON.stringify({
          error: "Payment gateway is not configured.",
          code: "PAYMENT_NOT_CONFIGURED"
        }),
        { status: 503 }
      );
    }
