async function handleCancelSubscription(request3, env2) {
  try {
    const payload = await requireAuth(request3, env2);
    const sub = await env2.DB.prepare(
      `SELECT * FROM Subscriptions WHERE user_id = ? AND status IN ('active','authenticated','created') ORDER BY created_at DESC LIMIT 1`
    ).bind(payload.sub).first();
    if (!sub)
      return new Response(
        JSON.stringify({ error: "No active subscription found" }),
        { status: 404 }
      );
    const razorpayKey = await getSecret(env2, "RAZORPAY_KEY_ID");
    const razorpaySecret = await getSecret(env2, "RAZORPAY_KEY_SECRET");
    if (razorpayKey && razorpaySecret && sub.razorpay_subscription_id) {
      await fetch(
        `https://api.razorpay.com/v1/subscriptions/${sub.razorpay_subscription_id}/cancel`,
        {
          method: "POST",
          headers: {
            Authorization: "Basic " + btoa(`${razorpayKey}:${razorpaySecret}`),
            "Content-Type": "application/json"
          },
          body: JSON.stringify({ cancel_at_cycle_end: 1 })
        }
      );
    }
    await env2.DB.prepare("UPDATE Subscriptions SET status = ? WHERE id = ?").bind("cancelled", sub.id).run();
    await createNotification(
      env2,
      payload.sub,
      "Subscription Cancelled",
      "Aapka subscription cancel ho gaya hai. Access period end tak active rahega.",
      "info"
    );
    return new Response(
      JSON.stringify({
        success: true,
        message: "Subscription cancelled. Access will remain until end of current period."
      }),
      { status: 200 }
    );
  } catch (error4) {
    return handleGlobalError(error4, "Subscription.Cancel", env2, request3);
  }
}
