async function handleAdminPlanPool(request3, env2, planId) {
  try {
    await requireAdmin(request3, env2);
    if (request3.method === "GET") {
      const { results } = await env2.DB.prepare(
        `SELECT pcp.*, c.title as course_title, b.name as batch_name, bo.title as book_title
         FROM PlanContentPool pcp
         LEFT JOIN Courses c ON pcp.item_type = 'course' AND pcp.item_id = c.id
         LEFT JOIN Batches b ON pcp.item_type = 'batch' AND pcp.item_id = b.id
         LEFT JOIN Books bo ON pcp.item_type = 'book' AND pcp.item_id = bo.id
         WHERE pcp.plan_id = ? ORDER BY pcp.item_type, pcp.access_mode`
      ).bind(planId).all();
      return new Response(JSON.stringify({ pool: results }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    if (request3.method === "POST") {
      const items = await request3.json();
      if (!Array.isArray(items) || items.length === 0) {
        return new Response(JSON.stringify({ error: "items array required" }), {
          status: 400
        });
      }
      const stmts = items.map(
        (item) => env2.DB.prepare(
          `INSERT OR REPLACE INTO PlanContentPool (id, plan_id, item_type, item_id, access_mode, bonus_ai_credits)
           VALUES (?, ?, ?, ?, ?, ?)`
        ).bind(
          generateCustomId("YA-PCP"),
          planId,
          item.item_type,
          item.item_id,
          item.access_mode,
          item.bonus_ai_credits || 0
        )
      );
      await env2.DB.batch(stmts);
      return new Response(
        JSON.stringify({ success: true, added: items.length }),
        { status: 201, headers: { "Content-Type": "application/json" } }
      );
    }
    if (request3.method === "DELETE") {
      const { item_type, item_id } = await request3.json();
      await env2.DB.prepare(
        "DELETE FROM PlanContentPool WHERE plan_id = ? AND item_type = ? AND item_id = ?"
      ).bind(planId, item_type, item_id).run();
      return new Response(JSON.stringify({ success: true }), {
        status: 200,
        headers: { "Content-Type": "application/json" }
      });
    }
    return new Response("Method not allowed", { status: 405 });
  } catch (error4) {
    if (error4.message === "Unauthorized" || error4.message === "Forbidden")
      return new Response(JSON.stringify({ error: error4.message }), {
        status: error4.message === "Unauthorized" ? 401 : 403
      });
    return handleGlobalError(error4, "Admin.PlanPool", env2, request3);
  }
}
