async function handleAdminSendEmail(request3, env2) {
  try {
    const adminId = await requireAdmin(request3, env2);
    const { to, subject, body, isHtml } = await request3.json();
    if (!to || !subject || !body) {
      return new Response(
        JSON.stringify({ error: "To, Subject, and Body are required" }),
        { status: 400 }
      );
    }
    let textFallback = "Please view this email in an HTML compatible client.";
    let htmlContent = body;
    if (!isHtml) {
      textFallback = body;
      htmlContent = `<p>${body}</p>`;
    }
    const success = await safeSendEmail(
      env2,
      to,
      subject,
      subject,
      htmlContent,
      textFallback
    );
    if (success) {
      return new Response(
        JSON.stringify({ success: true, message: "Email sent successfully" }),
        { status: 200 }
      );
    } else {
      return new Response(JSON.stringify({ error: "Failed to send email" }), {
        status: 500
      });
    }
  } catch (error4) {
    return handleGlobalError(error4, "Admin.SendEmail", env2, request3);
  }
}
